for i,l in enumerate(L):
  f=f'src/locales/{l}.json'; j=json.load(open(f)); y={}
  for k,v in K.items():
    assert len(v)==13,k
    d=y; ps=k.split('.')
    for p in ps[:-1]: d=d.setdefault(p,{})
    d[ps[-1]]=v[i]
  j['gr']=y; json.dump(j,open(f,'w'),ensure_ascii=False,indent=2); open(f,'a').write('\n')
